<template>
  <main class="content-page crypto-page">
    <header class="lab-heading"><p class="section-kicker">SPACE / CRYPTO LAB</p><h1>看见数据，<br><span>如何变成秘密。</span></h1><p>输入你的示例，单步观察每次计算。算法、原理图与实时数据放在一起。</p></header>
    <nav class="algorithm-tabs" aria-label="密码算法"><button v-for="item in ALGORITHMS" :key="item.id" type="button" :aria-pressed="algorithm===item.id" @click="algorithm=item.id">{{item.name}}<small>{{item.kind}}</small></button></nav>
    <div class="lab-layout"><section class="lab-workbench">
      <form class="lab-inputs" @submit.prevent="run"><h2>{{current.name}} 实验输入</h2><p>{{current.hint}}</p>
        <template v-if="algorithm==='aes'"><label>明文 HEX<textarea v-model="text" maxlength="64" spellcheck="false" /></label><label>密钥 HEX<input v-model="key" maxlength="64" spellcheck="false" /></label></template>
        <template v-else-if="algorithm==='rsa'"><div class="number-inputs"><label>素数 p<input v-model="p" type="number" min="3" max="997" /></label><label>素数 q<input v-model="q" type="number" min="3" max="997" /></label><label>公钥指数 e<input v-model="e" type="number" min="3" /></label><label>消息整数 m<input v-model="message" type="number" min="0" /></label></div></template>
        <template v-else-if="algorithm==='dh'"><div class="number-inputs"><label>公共素数 p<input v-model="p" type="number" min="5" max="997" /></label><label>公共底数 g<input v-model="g" type="number" min="2" /></label><label>Alice 指数 a<input v-model="a" type="number" min="1" /></label><label>Bob 指数 b<input v-model="b" type="number" min="1" /></label></div></template>
        <template v-else><label>示例文本<textarea v-model="text" maxlength="256" spellcheck="false" /></label><label v-if="algorithm==='caesar'">字母偏移<input v-model="shift" type="number" min="0" max="25" /></label><label v-if="['vigenere','xor'].includes(algorithm)">演示密钥<input v-model="key" maxlength="32" spellcheck="false" /></label><label v-if="['caesar','vigenere'].includes(algorithm)" class="check-label"><input v-model="reverse" type="checkbox" /> 反向解密</label></template>
        <div class="lab-actions"><button type="submit" class="button button-primary">计算并生成轨迹</button><button class="button button-secondary" type="button" @click="example">载入标准示例</button><button class="text-button" type="button" @click="clear">清除输入与轨迹</button></div><p v-if="error" class="lab-error" role="alert">{{error}}</p>
      </form>
      <section v-if="trace" class="trace-panel" aria-label="逐步计算"><div class="trace-controls"><button type="button" :disabled="cursor===0" @click="move(-1)">← 上一步</button><button type="button" :disabled="!trace.steps.length || cursor===trace.steps.length-1" @click="toggle">{{playing?'暂停':'自动播放'}}</button><button type="button" :disabled="cursor===trace.steps.length-1" @click="move(1)">下一步 →</button><label>速度<select v-model.number="speed"><option :value="900">慢</option><option :value="450">中</option><option :value="180">快</option></select></label></div><label class="trace-range">步骤 {{cursor+1}} / {{trace.steps.length}}<input v-model.number="cursor" type="range" min="0" :max="trace.steps.length-1" @input="stop" /></label>
        <h3>{{step?.title || '空输入'}}</h3><p class="trace-note">{{step?.note || '没有字符需要逐个处理。'}}</p>
        <div class="state-values" :class="{'state-matrix':step?.matrix}"><div v-for="(value,i) in step?.values" :key="i" :class="{changed:prior && prior.values[i]!==value}"><small>{{step.labels?.[i] || (step.matrix ? `行 ${Math.floor(i/4)} · 列 ${i%4}` : `#${i}`)}}</small><code>{{value}}</code></div></div>
        <p class="trace-legend">蓝色格表示与上一步显示值不同。AES 矩阵每格一个字节；SHA 寄存器每格一个 32 位字。</p><div v-if="step?.details" class="trace-details"><code v-for="line in step.details" :key="line">{{line}}</code></div>
        <details class="trace-list"><summary>选择任意计算步骤</summary><ol><li v-for="(item,i) in trace.steps" :key="i"><button type="button" :aria-current="cursor===i?'step':undefined" @click="stop();cursor=i">{{i+1}} · {{item.title}}</button></li></ol></details>
        <div class="trace-result"><h3>最终结果</h3><output>{{trace.result || '（空文本）'}}</output><button class="text-button" type="button" @click="download">下载本次轨迹 JSON ↗</button><small>仅主动下载时写入你选择的下载目录。</small></div>
      </section><p v-else class="trace-empty">修改输入后旧轨迹立即清空。点击“计算并生成轨迹”，开始观察实际计算。</p>
    </section><aside class="lab-principle"><p class="section-kicker">WHY IT WORKS</p><h2>原理与流程图</h2><p>{{current.principle}}</p><div class="principle-diagram" role="img" :aria-label="current.flow.join(' → ')"><div v-for="(label,i) in current.flow" :key="label" class="diagram-node" :class="{active:trace && step?.phase===i}"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{label}}</strong><svg v-if="i<current.flow.length-1" width="24" height="28" viewBox="0 0 24 28" aria-hidden="true"><path d="M12 1v20m-6-6 6 6 6-6" fill="none" stroke="currentColor" stroke-width="2" /></svg></div></div><p class="lab-warning">{{current.warning}}</p><a v-if="current.source" :href="current.source" target="_blank" rel="noopener noreferrer">核对 {{current.sourceTitle}} ↗</a><details class="core-code"><summary>查看核心计算函数</summary><p>直接运行的 JavaScript 函数。编码、常数表与辅助函数位于同一模块，未在此展开。没有动态执行用户代码。</p><pre><code>{{sourceCode}}</code></pre></details></aside></div>
    <p class="lab-privacy">全部演示在浏览器内运行，不上传、不存 localStorage，不调用大模型。只使用示例数据，不要填真实密码或私钥。本页是教学可视化，不是生产密码服务。</p>
  </main>
</template>
<script setup>
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { ALGORITHMS } from '../features/crypto/catalog'
import { aes128Trace,sha256Trace,rsaTrace,dhTrace,caesar,vigenere,xorTrace } from '../features/crypto/algorithms'
const functions={aes:aes128Trace,sha:sha256Trace,rsa:rsaTrace,dh:dhTrace,caesar,vigenere,xor:xorTrace}
const algorithm=ref('aes'), text=ref(''), key=ref(''), shift=ref(3), reverse=ref(false), p=ref(61), q=ref(53), e=ref(17), message=ref(65), g=ref(5), a=ref(6), b=ref(15)
const trace=ref(null), cursor=ref(0), playing=ref(false), speed=ref(900), error=ref(''); let timer
const current=computed(()=>ALGORITHMS.find(item=>item.id===algorithm.value)), step=computed(()=>trace.value?.steps[cursor.value]), prior=computed(()=>cursor.value>0?trace.value?.steps[cursor.value-1]:null), sourceCode=computed(()=>functions[algorithm.value].toString())
function stop(){clearInterval(timer);playing.value=false}
function invalidate(){stop();trace.value=null;cursor.value=0;error.value=''}
watch([text,key,shift,reverse,p,q,e,message,g,a,b],invalidate,{flush:'sync'})
watch(algorithm,example)
function example(){invalidate();reverse.value=false;shift.value=3;key.value=algorithm.value==='aes'?'000102030405060708090a0b0c0d0e0f':algorithm.value==='vigenere'?'LEMON':'Space';text.value=algorithm.value==='aes'?'00112233445566778899aabbccddeeff':algorithm.value==='sha'?'abc':algorithm.value==='vigenere'?'ATTACK AT DAWN':'Hello, Space!';p.value=algorithm.value==='dh'?23:61;q.value=53;e.value=17;message.value=65;g.value=5;a.value=6;b.value=15}
function run(){invalidate();try{const id=algorithm.value;trace.value=id==='aes'?aes128Trace(text.value,key.value):id==='sha'?sha256Trace(text.value):id==='rsa'?rsaTrace(p.value,q.value,e.value,message.value):id==='dh'?dhTrace(p.value,g.value,a.value,b.value):id==='caesar'?caesar(text.value,shift.value,reverse.value):id==='vigenere'?vigenere(text.value,key.value,reverse.value):xorTrace(text.value,key.value)}catch(ex){error.value=ex.message}}
function move(delta){stop();cursor.value=Math.max(0,Math.min(trace.value.steps.length-1,cursor.value+delta))}
function toggle(){if(playing.value){stop();return}playing.value=true;timer=setInterval(()=>{if(cursor.value>=trace.value.steps.length-1)stop();else cursor.value++},speed.value)}
watch(speed,()=>{if(playing.value){stop();toggle()}})
function visibility(){if(document.hidden)stop()}
function clear(){invalidate();text.value='';key.value='';p.value='';q.value='';e.value='';message.value='';g.value='';a.value='';b.value=''}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify({algorithm:current.value.name,warning:current.value.warning,...trace.value},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`space-${algorithm.value}-trace.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>{example();document.addEventListener('visibilitychange',visibility)});onUnmounted(()=>{stop();document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>
.lab-heading{padding:42px 0 28px}.lab-heading h1{font-size:clamp(38px,5vw,64px);line-height:1.15}.lab-heading h1 span{color:#0071e3}.lab-heading>p:last-child{font-size:18px;margin-top:22px;max-width:630px;line-height:1.8}.algorithm-tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:28px}.algorithm-tabs button{border:1px solid #dbe1e8;background:#fff;border-radius:16px;padding:13px 17px;text-align:left;font-size:16px;color:#303f50}.algorithm-tabs small{display:block;font-size:14px;margin-top:5px;color:#66768a}.algorithm-tabs button[aria-pressed=true]{background:#edf5ff;border-color:#0071e3;color:#0066cc}.lab-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:24px}.lab-workbench,.lab-principle{min-width:0}.lab-inputs,.trace-panel,.lab-principle{padding:26px;border:1px solid #dfe4eb;border-radius:24px;background:#fff}.lab-inputs p,.lab-principle p,.trace-note{font-size:16px;line-height:1.85;color:#526277;margin:16px 0}.lab-inputs label{display:grid;gap:9px;margin:16px 0;color:#42546b;font-size:16px}.lab-inputs input,.lab-inputs textarea,.trace-controls select{width:100%;min-width:0;border:1px solid #ced6e2;border-radius:12px;padding:12px;background:#fafbfd;color:#1d2737;font-size:16px}.lab-inputs textarea{min-height:82px;resize:vertical;font-family:ui-monospace,monospace}.number-inputs{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.lab-inputs .check-label{display:flex;align-items:center}.check-label input{width:20px}.lab-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.lab-error{color:#af2937!important}.trace-panel{margin-top:20px}.trace-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.trace-controls button{min-height:44px;border:1px solid #dae2ed;padding:10px 14px;background:#f5f8fc;border-radius:12px;color:#24547c;font-size:14px}.trace-controls label{display:flex;align-items:center;gap:8px;font-size:14px}.trace-controls select{width:64px;padding:8px}.trace-range{display:grid;gap:12px;margin:22px 0;font-size:14px}.trace-range input{width:100%;accent-color:#0071e3}.state-values{display:grid;grid-template-columns:repeat(auto-fit,minmax(105px,1fr));gap:8px}.state-values>div{background:#f4f5f7;border:1px solid #e6e8ed;border-radius:12px;min-width:0;padding:12px}.state-values small{display:block;font-size:14px;color:#65768a;margin-bottom:8px}.state-values code{font-size:16px;overflow-wrap:anywhere}.state-values .changed{background:#edf5ff;border-color:#a7cdf6}.state-values.state-matrix{grid-template-columns:repeat(4,minmax(0,1fr))}.trace-legend,.trace-result small,.lab-privacy{display:block;font-size:14px;line-height:1.9;color:#637083;margin:18px 0}.trace-details{display:grid;gap:8px;padding:14px;background:#f7f9fc;border-radius:12px}.trace-details code{font-size:14px;overflow-wrap:anywhere}.trace-list{margin:22px 0;font-size:16px}.trace-list ol{max-height:240px;overflow:auto;padding:12px 0;list-style:none}.trace-list button{border:0;background:transparent;padding:10px;color:#476487;text-align:left;font-size:14px}.trace-list button[aria-current=step]{background:#edf5ff;color:#0066cc}.trace-result{border-top:1px solid #e6e9ef;padding-top:20px}.trace-result output{display:block;font-size:16px;overflow-wrap:anywhere;font-family:ui-monospace,monospace;line-height:1.8;margin:12px 0}.trace-empty{padding:24px;line-height:1.8;color:#627186}.principle-diagram{padding:10px 0 26px}.diagram-node{position:relative;display:flex;align-items:center;gap:14px;min-height:64px;margin-bottom:24px;border:1px solid #e1e7ef;border-radius:14px;padding:12px 14px;background:#f7f9fc;font-size:16px}.diagram-node>span{color:#8a9cb2;font-size:14px}.diagram-node svg{position:absolute;left:calc(50% - 12px);bottom:-27px;color:#b7c5d4}.diagram-node.active{border-color:#0071e3;background:#edf5ff;color:#0066cc}.lab-warning{padding-top:20px;border-top:1px solid #e5e9ef}.lab-principle>a{font-size:14px;color:#0066cc}.core-code{margin-top:24px;font-size:16px}.core-code pre{max-height:400px;overflow:auto;font-size:14px;padding:12px;background:#f4f6f9;white-space:pre-wrap;overflow-wrap:anywhere}.lab-privacy{margin:32px 0}button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:850px){.lab-layout{grid-template-columns:1fr}}@media(max-width:480px){.lab-inputs,.trace-panel,.lab-principle{padding:18px}.state-values>div{padding:9px}.state-values.state-matrix small{font-size:14px}.lab-heading{padding-top:24px}}
</style>
